#!/usr/bin/env python3
"""Ross's transcript helper: append missing Friend-Message utterances to episode files.
Reads commits from the six friend/* branches via git (in the conversation worktree),
compares SHAs against existing Source: lines, and appends new entries in
(commit-time, full-SHA) order. Never rewrites existing content.

Usage: fwork-transcribe.py <main-worktree> <git-repo-dir> [--apply]
"""
import re, subprocess, sys, os, pathlib

BRANCHES = ["rachel", "monica", "phoebe", "joey", "chandler", "ross"]
SRC_RE = re.compile(r"Source: friend/([a-z]+) @ ([0-9a-f]{40})")

def git(repo, *args):
    return subprocess.run(["git", "-C", repo] + list(args), capture_output=True, text=True).stdout

def collect(repo):
    rows = []
    for b in BRANCHES:
        out = git(repo, "log", "--format=%H|%cI|%s", f"origin/friend/{b}",
                  "--grep=Friend-Message: 1", "--fixed-strings")
        for line in out.splitlines():
            if not line.strip():
                continue
            sha, ts, subj = line.split("|", 2)
            rows.append({"sha": sha, "ts": ts, "branch": b})
    return rows

def parse_commit(repo, sha):
    body = git(repo, "show", "-s", "--format=%B", sha)
    lines = body.split("\n")
    meta = {}
    i = 0
    for idx, ln in enumerate(lines):
        if ln.startswith("Reply-To:"):
            meta["reply_to"] = ln.split(":", 1)[1].strip()
            i = idx + 1
            break
    # skip blank lines after Reply-To
    while i < len(lines) and lines[i].strip() == "":
        i += 1
    text = "\n".join(lines[i:]).strip("\n")
    for key in ("Speaker", "Episode"):
        m = re.search(rf"^{key}: (.+)$", body, re.M)
        meta[key] = m.group(1).strip() if m else ""
    meta["text"] = text
    meta["sha"] = sha
    return meta

def main():
    main_wt, repo = sys.argv[1], sys.argv[2]
    apply = "--apply" in sys.argv
    episodes = {}
    for p in sorted(pathlib.Path(main_wt).glob("S*/E*.md")):
        episodes[p] = p.read_text()
    known = set()
    for p, txt in episodes.items():
        for m in SRC_RE.finditer(txt):
            known.add(m.group(2))
    rows = collect(repo)
    missing = [r for r in rows if r["sha"] not in known]
    seen, uniq = set(), []
    for r in missing:
        if r["sha"] in seen:
            continue
        seen.add(r["sha"]); uniq.append(r)
    uniq.sort(key=lambda r: (r["ts"], r["sha"]))
    if not uniq:
        print("nothing missing")
        return
    by_ep = {}
    for r in uniq:
        m = parse_commit(repo, r["sha"])
        ep = m.get("Episode") or "?"
        by_ep.setdefault(ep, []).append((r, m))
    for ep, items in by_ep.items():
        m = re.match(r"^S(\d{2})/E(\d{2})$", ep)
        if not m:
            print(f"WARN: unrecognized episode label {ep}: {[i[0]['sha'][:10] for i in items]}")
            continue
        path = pathlib.Path(main_wt) / f"S{m.group(1)}/E{m.group(2)}.md"
        if not path.exists():
            print(f"WARN: no file for {ep}; cannot append {len(items)} entries")
            continue
        blocks = []
        for r, meta in items:
            blocks.append(f"**{meta['Speaker']}** ({r['ts']})\n\nSource: friend/{r['branch']} @ {r['sha']}\n\n{meta['text']}\n")
        old = path.read_text()
        new = old.rstrip("\n") + "\n\n" + "\n".join(blocks)
        print(f"--- {path.name}: +{len(blocks)} entries")
        for r, meta in items:
            print(f"  {r['ts']} {meta['Speaker']:9s} {r['sha'][:10]} :: {meta['text'][:80]}")
        if apply:
            path.write_text(new)
    if not apply:
        print("(dry run; pass --apply to write)")

main()
PY
